arguments.command:
cd /workspace && python3 - <<'EOF'
import json, sys, importlib.util
sys.path.insert(0,'/workspace/tmp')
spec = importlib.util.spec_from_file_location('m','/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
src = open('/workspace/tmp/topo_cover.py').read().split('def main()')[0]
ns = {}; exec(src, ns)
sessions = [ns['build_session'](s) for s in ns['VARIANTS']]
req = {'version':2,'sessions':sessions}
try:
    d = m.transport(req); print('transport ok')
except Exception as e:
    print('transport FAIL', e)
    # bisect
    for i in range(len(sessions)):
        try:
            m.transport({'version':2,'sessions':sessions[:i+1]})
        except Exception as e2:
            print('  fails at session', i, ns['VARIANTS'][i], e2); break
EOF
